local _, ns = ...
if ns.LOCALE ~= "esES" then return end
local L = ns.L

-- Options/HelpPanes.lua: the FAQ and Support pages, beside Locales/esES.lua.
L["FAQ_CAPTION"] = "Preguntas frecuentes, y dónde quedaron las cosas."
L["FAQ_SEARCH"] = "Buscar preguntas"
L["FAQ_NONE"] = "Ninguna pregunta coincide."
L["FAQ_NOT_BOUND"] = "sin asignar"
L["FAQ_LFG_Q"] = "¿Dónde está mi botón LFG (buscador de grupos)?"
L["FAQ_LFG_A"] = "La 1.x no lo tenía, así que no está en el micromenú. Haz clic en el ojo del minimapa, usa las pestañas laterales de la pestaña Quién de la ventana social o pulsa la tecla del buscador de grupos (%s). Para recuperar el botón, desmarca \"%s\" en \"%s\"."
L["FAQ_LEGACY_Q"] = "¿Dónde está mi botón de Legado?"
L["FAQ_LEGACY_A"] = "1.x no tenía ninguno, así que no está en el micromenú. Haz clic en su icono del minimapa. Para recuperar el botón, desmarca \"%s\" en \"%s\". Cualquier botón del micromenú puede estar en el minimapa: márcalo en \"%s\"."
L["FAQ_PROFESSIONS_Q"] = "¿Dónde está mi botón de profesiones?"
L["FAQ_PROFESSIONS_A"] = "La 1.x no lo tenía, así que no está en el micromenú. Abre tus profesiones desde el libro de hechizos o pulsa la tecla de profesiones (%s). Para recuperar el botón, desmarca \"%s\" en \"%s\"."
L["FAQ_COLLECTIONS_Q"] = "¿Dónde está mi botón de colecciones?"
L["FAQ_COLLECTIONS_A"] = "La 1.x no lo tenía, así que no está en el micromenú. Abre tus monturas, mascotas, juguetes y apariencias desde la pestaña \"%s\" al pie del libro de hechizos, o pulsa la tecla de colecciones (%s). Para recuperar el botón, desmarca \"%s\" en \"%s\"."
L["FAQ_QUICKJOIN_Q"] = "¿Dónde está la pestaña %s?"
L["FAQ_QUICKJOIN_A"] = "En la ventana social, abre %s y luego %s. La pestaña %s bajo la lista cambia a ella y la pestaña %s vuelve atrás."
L["FAQ_REAGENT_Q"] = "¿Dónde está mi bolsa de componentes?"
L["FAQ_REAGENT_A"] = "Es la pequeña bolsa redonda entre el llavero y tu última bolsa, visible mientras el ratón está sobre tus bolsas. Para verla siempre, elige \"%s\", o \"%s\" para una ranura como las demás bolsas."
L["FAQ_TENBUTTONS_Q"] = "¿Por qué mi barra principal muestra 10 botones o el tamaño equivocado?"
L["FAQ_TENBUTTONS_A"] = "La banda sigue los ajustes de la barra de acción 1 en el modo edición: \"%s\" y \"%s\". \"%s\" en la página \"%s\" da los botones más pequeños de 1.x."
L["FAQ_GRYPHONS_Q"] = "¿Cómo oculto los grifos?"
L["FAQ_GRYPHONS_A"] = "En la página \"%s\", pon \"%s\" o \"%s\" en \"%s\". En el modo edición cada grifo es una pieza propia, para moverla u ocultarla."
L["FAQ_XPBAR_Q"] = "¿Puedo ocultar la barra de experiencia o sacarla de la banda?"
L["FAQ_XPBAR_A"] = "Sí, en el modo edición. Haz clic en la barra de experiencia o de reputación: se puede arrastrar fuera de la banda, y su cuadro tiene \"%s\"."
L["FAQ_SIZE_Q"] = "¿Por qué las ventanas son más pequeñas que las del juego? ¿Puedo agrandarlas?"
L["FAQ_SIZE_A"] = "Son los tamaños propios de Classic Era. Haz clic en el candado de la barra de título de una ventana y arrastra el tirador de su esquina, o ajusta su tamaño en el modo edición, en \"%s\". Las barras siguen \"%s\" y el tamaño en el cuadro de cada barra del modo edición."
L["FAQ_SCALE_Q"] = "¿Por qué mi interfaz se ve más grande?"
L["FAQ_SCALE_A"] = "Classic Era dibuja su interfaz más grande que Forever. Elegir el diseño clásico con el tamaño de Era pone la escala de la interfaz del juego en ese tamaño, 90%% en la mayoría de pantallas. Cámbiala cuando quieras en %s, en las opciones del juego (\"%s\")."
L["FAQ_SCALEBACK_Q"] = "¿Cómo recupero mi tamaño de interfaz anterior?"
L["FAQ_SCALEBACK_A"] = "Pulsa \"%s\" en la barra lateral con \"%s\" marcada: tu tamaño de antes vuelve con las opciones. O ajústalo en %s, en las opciones del juego; desmarca \"%s\" para el tamaño automático del juego."
L["FAQ_GLOW_Q"] = "¿Cómo quito el brillo rojo de mis marcos?"
L["FAQ_GLOW_A"] = "En la página \"%s\": \"%s\" para el brillo rojo cuando algo va a por ti, \"%s\" para el pulso de tu marco de jugador mientras atacas."
L["FAQ_TRACKER_Q"] = "¿Puedo recuperar el antiguo seguimiento de misiones?"
L["FAQ_TRACKER_A"] = "Sí. En la página \"%s\", \"%s\" elige su aspecto, entre ellos el seguimiento de misiones de Classic Era."
L["FAQ_PLATES_Q"] = "¿Cómo agrando las placas de nombre?"
L["FAQ_PLATES_A"] = "Su tamaño es del propio juego, en \"%s\" en sus Opciones. \"%s\" en la página \"%s\" cambia solo el nombre."
L["FAQ_MOVE_Q"] = "¿Puedo mover las ventanas?"
L["FAQ_MOVE_A"] = "Sí, fuera de combate. Pasa el ratón por la barra de título de una ventana y haz clic en su candado; luego arrástrala por el título. O coloca las ventanas en el modo de edición en \"%s\". El botón rojo junto al candado devuelve la ventana a su sitio por defecto."
L["FAQ_MOVERS_Q"] = "¿Por qué mi addon para mover ventanas mueve algunas y otras no?"
L["FAQ_MOVERS_A"] = "La hoja de personaje y otras ventanas del juego son las propias del juego con el aspecto de la 1.x, así que esos addons pueden moverlas; \"%s\" en las opciones se las deja por completo. Nuestro libro de hechizos y registro de misiones los hacemos nosotros, porque el juego no tiene ninguno como los de Era, y esos addons solo mueven las ventanas de su propia lista. Las nuestras se mueven con el candado de su barra de título o en el modo de edición."
L["FAQ_SETTING_Q"] = "¿Puedo cambiar cómo se ve o funciona algo?"
L["FAQ_SETTING_A"] = "Casi seguro. Casi todas las piezas se pueden desactivar o ajustar: escribe una palabra en el campo \"%s\" arriba a la izquierda de esta ventana. Si no lo encuentras, pregunta en GitHub o CurseForge."
L["FAQ_FOREVER_Q"] = "¿Puedo mantener el aspecto propio de Forever en algunas partes?"
L["FAQ_FOREVER_A"] = "Sí. Cada pieza clásica tiene su propio interruptor en esta ventana; desactívala y vuelve la de Forever. Algunos cambios necesitan recargar, y una ventana emergente te lo pide."
L["FAQ_OTHER_ADDON_Q"] = "¿Se puede hacer que %s funcione con otro accesorio?"
L["FAQ_OTHER_ADDON_A"] = "Dinos cuál en GitHub o CurseForge y lo miraremos. Cuando dos accesorios cambian la misma parte de la pantalla, desactivar esa parte aquí suele permitir que ambos funcionen."
L["FAQ_LFG_RETAIL_A"] = "La 1.x no lo tenía, así que no está en el micromenú. Haz clic en el ojo del minimapa o pulsa la tecla del buscador de grupos (%s). Para recuperar el botón, desmarca \"%s\" en \"%s\"."
L["FAQ_REAGENT_RETAIL_A"] = "Está en la antigua ranura del llavero, al final de tus bolsas. Para una ranura como las demás bolsas, elige \"%s\"."
L["FAQ_OWNLOOK_Q"] = "¿Puedo mantener el aspecto propio del juego en algunas partes?"
L["FAQ_OWNLOOK_A"] = "Sí. Cada pieza clásica tiene su propio interruptor en esta ventana; desactívala y vuelve la del juego. Algunos cambios necesitan recargar, y una ventana emergente te lo pide."
L["FAQ_RETAILBUTTONS_Q"] = "¿Dónde están mis botones de %s, %s y %s?"
L["FAQ_RETAILBUTTONS_A"] = "La 1.x no los tenía, así que no están en el micromenú. Haz clic en sus iconos del minimapa, o pulsa la tecla de %s (%s) o de %s (%s). Para recuperar un botón, desmárcalo en \"%s\"."
L["FAQ_SUITE_Q"] = "¿Qué es ClassicUI Forever?"
L["FAQ_SUITE_A"] = "El conjunto completo de complementos del que viene esta parte: todo el aspecto de la 1.x, desde las barras y bolsas hasta los marcos de unidad, los mapas y las ventanas. Solo funciona uno a la vez, así que para más que esta parte, usa ClassicUI Forever completo y desactiva lo que no quieras."
L["FAQ_SUITE_PICKER_A"] = "El conjunto completo de complementos para el que se hizo primero este selector de color: todo el aspecto de la 1.x, desde las barras y bolsas hasta los marcos de unidad, los mapas y las ventanas, con este selector de color incluido. Solo funciona uno a la vez, así que para tener ambos, usa ClassicUI Forever completo."
L["FAQ_MICRO_KEY_A"] = "La 1.x no lo tenía, así que no está en el micromenú. Pulsa su tecla (%s). Para recuperar el botón, desmarca \"%s\" en \"%s\"."
L["FAQ_MICRO_OFF_A"] = "La 1.x no lo tenía, así que no está en el micromenú. Para recuperar el botón, desmarca \"%s\" en \"%s\"."
L["FAQ_RETAILBUTTONS_KEY_A"] = "La 1.x no los tenía, así que no están en el micromenú. Pulsa la tecla de %s (%s) o de %s (%s). Para recuperar un botón, desmárcalo en \"%s\"."
L["SUPPORT_CAPTION"] = "Gracias por usar %s."
L["SUPPORT_FEEDBACK_HEAD"] = "Comentarios"
L["SUPPORT_FEEDBACK"] = "Los informes de errores, las ideas y cualquier otro comentario siempre son bienvenidos. Antes de escribir, pulsa %s y pega en tu informe lo que te da: tu configuración, la versión del juego y tus otros addons."
L["SUPPORT_POST"] = "Luego elige dónde publicarlo. Los botones copian la dirección para pegarla en tu navegador."
L["SUPPORT_MORE_HEAD"] = "También te puede gustar"
L["SUPPORT_MORE"] = "EasyFind, también nuestro: una paleta de comandos para el juego. Escribe lo que quieres y hazlo directamente desde los resultados: abre una ventana o un ajuste, monta, lanza un hechizo o encuentra un lugar en el mapa."
L["SUPPORT_MORE_BUTTON"] = "EasyFind en CurseForge"
L["SUPPORT_SUITE_BUTTON"] = "ClassicUI Forever en CurseForge"
L["SUPPORT_DONATE_HEAD"] = "Apoyar el accesorio"
L["SUPPORT_DONATE"] = "%s es gratuito. Si quieres apoyarlo, puedes hacerlo a través de Buy Me a Coffee."
L["SUPPORT_DONATE_BUTTON"] = "Buy Me a Coffee"

-- Era's interface size (Options/EraScale.lua).
L["ERASCALE_OFFER"] = "Classic Era muestra su interfaz más grande que Forever por defecto. ¿Cambiar al tamaño de Era, con las barras de tamaño clásico? La interfaz se recarga. El ajuste %s del juego cambia el tamaño cuando quieras."
L["ERASCALE_GIVEN_BACK"] = "Tamaño de la interfaz restablecido. ¿Se ve distinto de lo que esperabas? Haz clic %s."
L["ERASCALE_HELP"] = "El tamaño de la interfaz volvió al de antes de que el diseño clásico lo cambiara, o al tamaño automático del juego. Si aún se ve demasiado grande o pequeño, ajústalo en %s, en las opciones del juego: desmarca \"%s\" para el tamaño automático, o mueve su control deslizante."
L["ERASCALE_OPEN_SETTINGS"] = "Opciones del juego"
L["ERASCALE_SWITCH"] = "Usar el tamaño de Era"
L["ERASCALE_ASK"] = "Tu interfaz tiene en esta pantalla otro tamaño que la de Classic Era. ¿Cambiar al tamaño de Era, con las barras de tamaño clásico? El ajuste %s del juego lo cambia cuando quieras."
L["ERASCALE_KEEP"] = "Mantener mi tamaño"
